import{_ as a,o as s,c as t,ag as o}from"./chunks/framework.BPmc_f4o.js";const k=JSON.parse('{"title":"Workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"guides/workspaces.md","filePath":"guides/workspaces.md"}'),i={name:"guides/workspaces.md"};function n(r,e,c,l,h,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="workspaces" tabindex="-1">Workspaces <a class="header-anchor" href="#workspaces" aria-label="Permalink to &quot;Workspaces&quot;">​</a></h1><p>A <strong>workspace</strong> is a self-contained folder that holds everything Muxit needs to run your lab: device connectors, automation scripts, dashboards, drivers, and configuration.</p><h2 id="what-s-inside-a-workspace" tabindex="-1">What&#39;s Inside a Workspace <a class="header-anchor" href="#what-s-inside-a-workspace" aria-label="Permalink to &quot;What&#39;s Inside a Workspace&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-workspace/</span></span>
<span class="line"><span>  config/         Server settings (server.json, ai-memory.json)</span></span>
<span class="line"><span>  connectors/     Device configurations (.js files)</span></span>
<span class="line"><span>  scripts/        Automation scripts (.js files)</span></span>
<span class="line"><span>  dashboards/     Dashboard layouts (.dashboard.json)</span></span>
<span class="line"><span>  agents/         AI agent configs (.agent.json)</span></span>
<span class="line"><span>  drivers/</span></span>
<span class="line"><span>    community/    Free extension drivers (.dll)</span></span>
<span class="line"><span>    premium/      Licensed drivers (.dll)</span></span>
<span class="line"><span>  data/           Sandboxed file storage</span></span></code></pre></div><h2 id="files-outside-the-workspace" tabindex="-1">Files outside the workspace <a class="header-anchor" href="#files-outside-the-workspace" aria-label="Permalink to &quot;Files outside the workspace&quot;">​</a></h2><p>Muxit keeps to the workspace. Nothing you write in Muxit can read or write a file elsewhere on the computer:</p><ul><li><strong>Scripts and connector files</strong> run in a sandbox with no file access at all — no <code>fs</code>, no <code>require</code>.</li><li><strong>The editor, the Explorer and the AI</strong> (chat and MCP file tools) only see the workspace.</li><li><strong>Built-in drivers that take a path</strong> only accept paths inside the workspace: the <a href="/reference/drivers/file-access.html">File Access</a> base folder, <a href="/reference/drivers/email-notifier.html">e-mail</a> attachments, <a href="/reference/drivers/webhook-notifier.html">webhook</a> images, camera recording names and <a href="/reference/drivers/label-printer.html">label</a> templates. A relative path resolves against the workspace; a path that leads out of it — absolute, through <code>..</code>, or through a symbolic link — is refused with <code>PATH_OUTSIDE_WORKSPACE</code>.</li></ul><p>The exception is drivers written in <strong>Python or C#</strong>. They run with your own user rights, like any program you install, so they can reach the whole computer. Install only drivers you trust.</p><p>Muxit itself also keeps a few files outside the workspace for its own use: the workspace list, logs and the license cache, in <code>~/.muxit</code> (<code>%LOCALAPPDATA%\\Muxit</code> on Windows). The <strong>New Workspace</strong> and <strong>Open Workspace</strong> dialogs can browse your folders, because that is where you pick a workspace&#39;s location.</p><h2 id="first-run-setup" tabindex="-1">First-Run Setup <a class="header-anchor" href="#first-run-setup" aria-label="Permalink to &quot;First-Run Setup&quot;">​</a></h2><p>On a fresh install Muxit creates a workspace for you and opens straight into it — no setup screen. It is called <strong>Default</strong>, comes seeded with the example connectors, scripts and dashboards, and lives in a <code>workspace/</code> folder next to the Muxit binary (<code>%LOCALAPPDATA%\\Muxit\\workspace</code> for the standard Windows install). If that location isn&#39;t writable, Muxit falls back to <code>%LOCALAPPDATA%\\Muxit\\workspace</code> on Windows or <code>~/.muxit/workspace</code> on macOS/Linux. The path is printed in the startup log and named by the title-bar <strong><code>Workspace: &lt;name&gt;</code></strong> menu.</p><p>If you&#39;d rather start somewhere else, use <strong>New Workspace…</strong> or <strong>Open Workspace…</strong> from that menu — nothing is locked in.</p><p>Everything Muxit keeps <em>about</em> workspaces rather than <em>in</em> them — the catalog of known workspaces (<code>workspaces.json</code>), instance locks, logs and the license cache — lives in a per-user data directory: <code>~/.muxit</code> on macOS and Linux, <code>%LOCALAPPDATA%\\Muxit</code> on Windows. Set the <code>MUXIT_DATA_DIR</code> environment variable to move all of it somewhere else, for a portable install or a bench machine where each person wants their own catalog.</p><h3 id="self-repair" tabindex="-1">Self-repair <a class="header-anchor" href="#self-repair" aria-label="Permalink to &quot;Self-repair&quot;">​</a></h3><p>Muxit checks the workspace layout on <strong>every</strong> start and puts back anything missing: absent folders are recreated, and a workspace with no <code>config/server.json</code> gets one written with sensible defaults. So an interrupted first run, or a folder deleted by hand, fixes itself on the next launch instead of leaving a workspace that looks fine but can&#39;t be edited. What it does <em>not</em> do is bring back files you deleted on purpose: example content is seeded once, recorded in <code>.muxit/seeded.json</code>, and never copied again. Self-repair also never touches the workspace&#39;s display name — a workspace that is already in the catalog keeps the name you gave it; only a workspace seen for the first time is registered as <strong>Default</strong>.</p><h2 id="the-workspace-menu" tabindex="-1">The Workspace Menu <a class="header-anchor" href="#the-workspace-menu" aria-label="Permalink to &quot;The Workspace Menu&quot;">​</a></h2><p>The titlebar shows a <strong><code>Workspace: &lt;name&gt;</code></strong> menu (replacing what used to live under File). Every workspace operation hangs off this one menu:</p><ul><li><strong>Rename Workspace…</strong> --- change the display name of the current workspace. The folder on disk is untouched and no restart is needed.</li><li><strong>Switch to</strong> <em>(inline list)</em> --- one click switches to any other workspace in your catalog. No dialog.</li><li><strong>Open Workspace…</strong> --- open the picker dialog to browse to a workspace that isn&#39;t in the catalog yet.</li><li><strong>New Workspace…</strong> --- create a new workspace folder + register it.</li></ul><h2 id="creating-a-new-workspace" tabindex="-1">Creating a New Workspace <a class="header-anchor" href="#creating-a-new-workspace" aria-label="Permalink to &quot;Creating a New Workspace&quot;">​</a></h2><p>From the <strong>Workspace</strong> menu in the titlebar, select <strong>New Workspace…</strong>. This opens a dialog where you can specify:</p><ul><li><strong>Location</strong> --- The filesystem path where the workspace will be created (e.g., <code>/home/user/my-lab</code> or <code>C:\\Users\\me\\Documents\\my-lab</code>).</li><li><strong>Name</strong> (optional) --- A friendly name for the workspace. Defaults to the folder name.</li><li><strong>Include example content</strong> --- on by default. Copies the example connectors, scripts and dashboards in as a starting point. Untick it for an empty workspace; the choice is remembered, so the examples aren&#39;t added later.</li></ul><p>Muxit creates the standard directory structure and a minimal <code>server.json</code> configuration file.</p><p>The location must be a new or empty folder (or an existing workspace) — Muxit won&#39;t scatter its folders into a directory that already holds something else.</p><h2 id="opening-an-existing-workspace" tabindex="-1">Opening an Existing Workspace <a class="header-anchor" href="#opening-an-existing-workspace" aria-label="Permalink to &quot;Opening an Existing Workspace&quot;">​</a></h2><p>From the <strong>Workspace</strong> menu, select <strong>Open Workspace…</strong>. The dialog shows:</p><ul><li>A list of all previously opened workspaces, sorted by last-opened time</li><li>The currently active workspace (highlighted with a &quot;current&quot; badge)</li><li>An option to create a new workspace</li></ul><p>Click any workspace in the list to switch to it. Muxit will restart automatically with the selected workspace.</p><h2 id="renaming-a-workspace" tabindex="-1">Renaming a Workspace <a class="header-anchor" href="#renaming-a-workspace" aria-label="Permalink to &quot;Renaming a Workspace&quot;">​</a></h2><p>The default name of a workspace is the folder name — so if your workspace lives in <code>~/workspace/</code> you&#39;d see &quot;Workspace: workspace&quot; in the titlebar, which isn&#39;t very informative. From the <strong>Workspace</strong> menu, select <strong>Rename Workspace…</strong> to give it a clearer label (e.g. &quot;Optics Lab&quot;, &quot;Robot Cell 3&quot;). The rename only touches the catalog (<code>workspaces.json</code>); your folder on disk keeps its original name.</p><h2 id="switching-workspaces" tabindex="-1">Switching Workspaces <a class="header-anchor" href="#switching-workspaces" aria-label="Permalink to &quot;Switching Workspaces&quot;">​</a></h2><p>When you switch workspaces, the server performs a graceful restart:</p><ol><li>All running scripts and agents are stopped</li><li>All connector connections are closed</li><li>The server shuts down</li><li>The launcher (or the server itself, when it was started directly) restarts the server with the new workspace path</li></ol><p>This process takes a few seconds — longer on a first start when drivers are scanned. The page shows <em>Waiting for the server to restart…</em> and polls until the new server answers <strong>for the target workspace</strong>, then reloads in place — the restarted server never opens a second browser tab. A server that is up but still booting is not good enough: the page keeps polling rather than reloading onto a half-started server. If the new workspace is configured for a different port or HTTPS setting the page waits for that origin instead and then redirects to it. Should the restart take more than two minutes the page reloads anyway; if the server has still not come back at that point, check the startup log (<strong>Restart Server…</strong> / the console) for the reason.</p><h2 id="managing-the-workspace-list" tabindex="-1">Managing the Workspace List <a class="header-anchor" href="#managing-the-workspace-list" aria-label="Permalink to &quot;Managing the Workspace List&quot;">​</a></h2><ul><li>Workspaces are automatically added to the list when you create or open them</li><li>Click the <strong>X</strong> button on any workspace entry to remove it from the list (this does <strong>not</strong> delete the workspace folder)</li><li>A workspace whose folder has been <strong>deleted</strong> is removed from the list automatically, at startup and whenever a list is shown (the startup picker, <strong>Switch to</strong> and <strong>Open Workspace…</strong>). Muxit treats a folder as deleted when the folder it lived in is still there but the workspace folder is not</li><li>A workspace on something that is <strong>not connected</strong> right now — a USB drive, a network share, a drive letter that is not mapped — stays in the list, dimmed with a &quot;missing&quot; badge, and works again once the drive is back. Remove it with <strong>X</strong> if it is gone for good</li></ul><p>When only one workspace is left in the list, Muxit opens it at startup without asking; the picker appears when there are two or more.</p><h2 id="eula-acknowledgement-sandbox-mode" tabindex="-1">EULA Acknowledgement &amp; Sandbox Mode <a class="header-anchor" href="#eula-acknowledgement-sandbox-mode" aria-label="Permalink to &quot;EULA Acknowledgement &amp; Sandbox Mode&quot;">​</a></h2><p>Every Muxit workspace must have an accepted workspace acknowledgement before the server will let any driver perform a hardware <strong>write</strong> (setting a property, calling an action, or running a script). Until the acknowledgement is accepted the workspace loads in <strong>Sandbox mode</strong>: reads and polling continue, but every write is refused with error code <code>EULA_NOT_ACCEPTED</code>.</p><h3 id="what-gets-stored" tabindex="-1">What gets stored <a class="header-anchor" href="#what-gets-stored" aria-label="Permalink to &quot;What gets stored&quot;">​</a></h3><p>Acceptance produces two files inside the workspace:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-workspace/</span></span>
<span class="line"><span>  .muxit/</span></span>
<span class="line"><span>    EULA-ACCEPTED.md     # Human-readable acknowledgement + signed footer</span></span>
<span class="line"><span>    eula-history.jsonl   # Append-only audit trail of accept events</span></span>
<span class="line"><span>    workspace.json       # Stable workspace ID used in the footer</span></span></code></pre></div><p>The accepted file is a full copy of the current canonical EULA followed by a footer that identifies <em>who</em> accepted <em>which</em> version, <em>when</em>, for <em>which</em> workspace, and the SHA256 hash of the canonical body text.</p><h3 id="accepting-via-the-ui" tabindex="-1">Accepting via the UI <a class="header-anchor" href="#accepting-via-the-ui" aria-label="Permalink to &quot;Accepting via the UI&quot;">​</a></h3><p>When the server reports Sandbox mode the web UI replaces the main view with a blocking modal that shows the EULA text, asks for an identifier (name or email), and requires a checkbox before the <strong>Accept</strong> button is enabled. On accept the server writes <code>.muxit/EULA-ACCEPTED.md</code> atomically, appends a history entry, and unlocks the workspace.</p><h3 id="accepting-from-the-command-line" tabindex="-1">Accepting from the command line <a class="header-anchor" href="#accepting-from-the-command-line" aria-label="Permalink to &quot;Accepting from the command line&quot;">​</a></h3><p>Headless installs (<code>--cli</code> / <code>--mcp</code> modes, CI pipelines) accept the EULA one of two ways:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Explicit subcommand — writes the acceptance file and exits</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> accept</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Jane Doe&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eula</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # prints the canonical text</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or set environment variables before launching the server</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MUXIT_EULA_ACCEPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MUXIT_EULA_USER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ci-bot&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/workspace</span></span></code></pre></div><p>The env-var flow is logged with <code>action: &quot;accepted_ci&quot;</code> in the history file so CI-initiated acceptances are distinguishable from human ones.</p><h3 id="when-re-acceptance-is-required" tabindex="-1">When re-acceptance is required <a class="header-anchor" href="#when-re-acceptance-is-required" aria-label="Permalink to &quot;When re-acceptance is required&quot;">​</a></h3><p>The server treats EULA versions as semver (<code>1.0.0</code>, <code>1.1.0</code>, <code>2.0.0</code>):</p><ul><li><strong>Patch bump</strong> (<code>1.0.0</code> → <code>1.0.1</code>) — formatting / typo fix only, prior acceptance remains valid.</li><li><strong>Minor / major bump</strong> — requires re-acceptance; the modal shows the new version and notes the previous accepted version in the history.</li></ul><p>Re-acceptance is also required if the accepted file is edited outside Muxit (hash mismatch → <code>EulaTampered</code>) or if only the footer is present (<code>EulaCorrupt</code>).</p><h3 id="shared-workspaces-git" tabindex="-1">Shared workspaces (Git) <a class="header-anchor" href="#shared-workspaces-git" aria-label="Permalink to &quot;Shared workspaces (Git)&quot;">​</a></h3><p>The <code>.muxit/</code> folder commits with the workspace, so a team-shared Git repository carries the accepted EULA with it. The hash check still runs per user so any tampering is detected.</p><h2 id="workspace-catalog" tabindex="-1">Workspace Catalog <a class="header-anchor" href="#workspace-catalog" aria-label="Permalink to &quot;Workspace Catalog&quot;">​</a></h2><p>Muxit stores the list of known workspaces in a catalog file outside any workspace: <code>workspaces.json</code> in the per-user data directory — <code>%LOCALAPPDATA%\\Muxit\\</code> on Windows, <code>~/.muxit/</code> on macOS and Linux, or wherever <code>MUXIT_DATA_DIR</code> points. This file persists across workspace switches and server restarts; entries for deleted folders are dropped from it as described under <a href="#managing-the-workspace-list">Managing the Workspace List</a>.</p><h2 id="command-line-usage" tabindex="-1">Command-Line Usage <a class="header-anchor" href="#command-line-usage" aria-label="Permalink to &quot;Command-Line Usage&quot;">​</a></h2><p>You can also specify a workspace directly when starting the server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=/path/to/my-workspace</span></span></code></pre></div><p>Or with the compiled binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">muxit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=/path/to/my-workspace</span></span></code></pre></div><p>The specified workspace is automatically registered in the catalog.</p>`,62)])])}const g=a(i,[["render",n]]);export{k as __pageData,g as default};
